// Menyatukan input dari Webhook website ATAU dari Form Trigger lokal.
const j = $input.item.json || {};
const bin = $input.item.binary || {};

const isWebhook = j.body !== undefined || j.headers !== undefined;
const src = isWebhook ? (j.body || {}) : j;

const pick = (...keys) => {
  for (const k of keys) {
    if (src[k] !== undefined && src[k] !== null && String(src[k]).trim() !== '') return src[k];
  }
  return '';
};

const brief = String(pick('brief', 'campaignBrief', 'topic', 'idea', 'prompt', 'Campaign Brief / Topik')).trim();
const campaignName = String(pick('campaignName', 'campaign', 'Nama Campaign')).trim();
const platform = String(pick('platform', 'Platform') || 'Instagram').trim();
const callbackUrl = String(pick('callbackUrl', 'callback_url')).trim();
const requestId = String(pick('requestId', 'request_id') || $execution.id);

if (!brief || brief.length < 3) {
  throw new Error('Brief/topik campaign kosong. Kirim field "brief" (webhook) atau isi "Campaign Brief / Topik" (form).');
}

// --- Tentukan aspect ratio -------------------------------------------------
// Prioritas: pilihan tombol user > hint dari teks brief > DEFAULT 9:16
let choice = String(pick('aspectRatio', 'ratio', 'resolution', 'Aspect Ratio') || 'auto').toLowerCase();

function ratioFromText(t) {
  const s = String(t || '').toLowerCase();
  if (/(16\s*[:x\/]\s*9|landscape|horizontal|widescreen|thumbnail|banner)/.test(s)) return '16:9';
  if (/(9\s*[:x\/]\s*16|vertical|portrait|story|stories|reel|reels|tiktok|shorts)/.test(s)) return '9:16';
  return null;
}

let aspectRatio;
if (/16\s*[:x]\s*9|landscape|horizontal/.test(choice)) {
  aspectRatio = '16:9';
} else if (/9\s*[:x]\s*16|vertical|portrait/.test(choice)) {
  aspectRatio = '9:16';
} else {
  aspectRatio = ratioFromText(brief) || '9:16';
}

const dimensions = aspectRatio === '16:9'
  ? { width: 1920, height: 1080, label: 'Landscape / Horizontal' }
  : { width: 1080, height: 1920, label: 'Vertical / Story-Reels' };

// --- Gambar referensi (opsional) -----------------------------------------
const imageUrl = String(pick('imageUrl', 'image_url', 'referenceImageUrl')).trim();
const imageBase64 = String(pick('imageBase64', 'image_base64')).trim();
const binKeys = Object.keys(bin);
const hasBinaryImage = binKeys.length > 0;
const hasImage = Boolean(imageUrl || imageBase64 || hasBinaryImage);

return {
  json: {
    source: isWebhook ? 'website_webhook' : 'local_form',
    requestId,
    receivedAt: new Date().toISOString(),
    campaignName,
    platform,
    brief,
    aspectRatio,
    dimensions,
    aspectRatioResolvedFrom: /16\s*[:x]\s*9|9\s*[:x]\s*16|vertical|portrait|landscape|horizontal/.test(choice) ? 'user_button' : (ratioFromText(brief) ? 'brief_text' : 'default'),
    hasImage,
    imageUrl,
    imageBase64,
    imageBinaryKey: hasBinaryImage ? binKeys[0] : '',
    callbackUrl
  },
  binary: $input.item.binary
};

const norm = $('Normalize Input').item.json;
const g = $input.item.json || {};
const insight = g.content || g.text || g.response ||
  (Array.isArray(g.candidates) && g.candidates[0] && g.candidates[0].content && g.candidates[0].content.parts && g.candidates[0].content.parts[0] && g.candidates[0].content.parts[0].text) ||
  '';
return { json: { ...norm, imageInsight: String(insight).trim() }, binary: $('Normalize Input').item.binary };

