const norm = $('Normalize Input').item.json;
let out = $input.item.json || {};
let post = (out.content !== undefined) ? out.content : out;

if (typeof post === 'string') {
  const cleaned = post.replace(/```json/gi, '').replace(/```/g, '').trim();
  try { post = JSON.parse(cleaned); }
  catch (e) { post = { headline: '', caption: cleaned, hashtags: [], call_to_action: '', image_prompt: norm.brief, carousel_slides: [], aspect_ratio: norm.aspectRatio, dimensions: norm.dimensions.width + 'x' + norm.dimensions.height, platform_notes: '' }; }
}

// jaga konsistensi rasio
post.aspect_ratio = norm.aspectRatio;
post.dimensions = norm.dimensions.width + 'x' + norm.dimensions.height;
if (!post.image_prompt) post.image_prompt = norm.brief;

return { json: { ...norm, post }, binary: $('Normalize Input').item.binary };

const base = $('Parse Campaign JSON').item.json;
const bin = $input.item.binary || {};
const img = bin.campaign_image;

return {
  json: {
    requestId: base.requestId,
    source: base.source,
    status: 'generated',
    generatedAt: new Date().toISOString(),
    campaignName: base.campaignName,
    platform: base.platform,
    brief: base.brief,
    aspectRatio: base.aspectRatio,
    dimensions: base.dimensions,
    aspectRatioResolvedFrom: base.aspectRatioResolvedFrom,
    post: base.post,
    image: img ? {
      fileName: img.fileName || ('campaign_' + base.requestId + '.png'),
      mimeType: img.mimeType || 'image/png',
      dataBase64: img.data || null
    } : null,
    callbackUrl: base.callbackUrl || ''
  },
  binary: bin
};

const p = $('Build Backend Payload').item.json;
const post = p.post || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const tags = Array.isArray(post.hashtags) ? post.hashtags.join(' ') : (post.hashtags || '');
const slides = Array.isArray(post.carousel_slides)
  ? post.carousel_slides.map((s) => `  ${s.slide || '-'}. <b>${esc(s.title)}</b> \u2014 ${esc(s.body)}`).join('\n')
  : '';

const dim = (p.dimensions && p.dimensions.width) ? `${p.dimensions.width}x${p.dimensions.height}` : esc(p.dimensions);

const summary =
  `\uD83D\uDE80 <b>${esc(post.headline || p.campaignName || 'Campaign')}</b>\n` +
  `\uD83D\uDCF1 ${esc(p.platform)}  |  \uD83D\uDDBC\uFE0F ${esc(p.aspectRatio)} (${dim})  |  \uD83E\uDDED ${esc(p.aspectRatioResolvedFrom)}\n` +
  `\uD83C\uDD94 <code>${esc(p.requestId)}</code> \u00B7 ${esc(p.source)}`;

let full =
  summary + `\n\n` +
  `\uD83D\uDCDD <b>Caption</b>\n${esc(post.caption)}\n\n` +
  (post.call_to_action ? `\uD83D\uDC49 <b>CTA:</b> ${esc(post.call_to_action)}\n\n` : '') +
  (tags ? `${esc(tags)}\n\n` : '') +
  (slides ? `\uD83C\uDF9E\uFE0F <b>Carousel</b>\n${slides}\n\n` : '') +
  (post.platform_notes ? `\u2139\uFE0F <b>Notes:</b> ${esc(post.platform_notes)}\n\n` : '') +
  `\uD83C\uDFA8 <b>Image prompt</b>\n${esc(post.image_prompt)}`;

if (full.length > 4000) full = full.slice(0, 3990) + '\u2026';
let caption = summary;
if (caption.length > 1000) caption = caption.slice(0, 1000);

const hasVisual = !!(($input.item.binary || {}).campaign_image);

return { json: { ...p, tgCaption: caption, tgFull: full, hasVisual }, binary: $input.item.binary };
